export const WEEKLY_SHEET = {
  file: "/exports/weekly-routine-full.md",
  copyText: "# 🏊 روتین کامل هفتگی ورزش — برنامهٔ شناگر FST-7\n\n> تولید 2026-10-27 — تک‌برگ مرجع برای ساخت برنامه در هر اپ یا روی کاغذ\n> هدف: فرم شناگری (V-Taper) + کاهش چربی\n> پروتئین: ۲ گرم به ازای هر کیلو وزن هدف | کسری کالری: ۵۰۰ | کراتین: ۳ تا ۵ گرم روزانه، هر ساعت از روز\n\n## 📅 تقویم هفته\n\n| روز | برنامه |\n|---|---|\n| شنبه | جلسه ۱ — Push |\n| یکشنبه | پیاده‌روی ۸–۱۰ هزار قدم + کشش |\n| دوشنبه | جلسه ۲ — Pull |\n| سه‌شنبه | پیاده‌روی / شنا |\n| چهارشنبه | جلسه ۳ — پا + شکم |\n| پنجشنبه | استراحت کامل |\n| جمعه | پیاده‌روی سبک |\n\n## 🔥 پروتکل هر جلسه (ترتیب دقیق)\n\n1. گرم‌کردن قبل از وزنه: ۵ دقیقه خیلی آسان (مقاومت کم) — ریتم پدال راحت — جوری که راحت حرف بزنی. بعدش برای حرکت اول جلسه، یک ست سبک اضافه بزن.\n2. ست‌های گرم‌کردنی حرکت اول: پرس سینه/پرس پا: ۱×۸ ۴۰٪ → ۱×۴ ۶۰٪ → ۱×۲ ۷۵٪ — بارفیکس: اسکاپولار پول + کش\n3. حرکات اصلی به ترتیب (تا RPE ۸–۹ — همیشه ۱–۳ تکرار در مخزن)\n4. فینیشر FST-7 (۷ ست ایزوله با ۳۰–۴۵ ثانیه استراحت)\n5. بعد از ست آخر: LISS دوچرخه ۱۵ تا ۲۰ دقیقه (ضربان ۱۱۵ تا ۱۳۵) — جایگزین تردمیل شیب‌دار\n6. سرد کردن: کشش‌های همان روز (~۵ دقیقه) — جدول پایین\n\n> چرا هفته‌های اول دستگاه‌محور؟ هر دو نسخه عضله می‌سازن — متاآنالیز ۲۰۲۳ هیچ تفاوت معناداری در رشد عضله بین دستگاه و وزنه آزاد پیدا نکرد. دستگاه برای تازه‌کار یعنی: یادگیری سریع‌تر الگو، امنیت بدون اسپاتر و تمرکز کامل روی عضله. از هفته سوم، نسخه وزنه آزاد رو کم‌کم وارد کن (سوییچ داخل هر کارت). خود دوریان ییتس هم زیربغلش رو با دستگاه می‌زد!\n\n## 🔀 دو نسخهٔ برنامه — دستگاه (هفتهٔ ۱–۲) ↔ وزنهٔ آزاد (هفتهٔ ۳+)\n\n| روز | حرکت (اسلات) | نسخهٔ دستگاهی | نسخهٔ وزنهٔ آزاد |\n|---|---|---|---|\n| شنبه | پرس سینه هالتر | پرس سینه دستگاه | پرس سینه هالتر |\n| شنبه | پرس بالاسینه دمبل | پرس بالاسینه دستگاه | پرس بالاسینه دمبل |\n| شنبه | پرس سرشانه دمبل نشسته | پرس سرشانه دستگاه | پرس سرشانه دمبل نشسته |\n| شنبه | کراس اور سیم‌کش سینه | کراس اور سیم‌کش سینه | قفسه سینه دمبل |\n| شنبه | پشت‌بازو سیم‌کش با طناب | پشت‌بازو سیم‌کش با طناب (هر دو نسخه یکسان) | پشت‌بازو سیم‌کش با طناب |\n| شنبه | نشر جانب دمبل | نشر جانب سیم‌کش | نشر جانب دمبل |\n| دوشنبه | بارفیکس | بارفیکس کمکی دستگاه | بارفیکس |\n| دوشنبه | زیربغل هالتر خم | زیربغل سیم‌کش نشسته | زیربغل هالتر خم |\n| دوشنبه | زیربغل سیم‌کش دست‌باز | زیربغل سیم‌کش دست‌باز (هر دو نسخه یکسان) | زیربغل سیم‌کش دست‌باز |\n| دوشنبه | فیس پول سیم‌کش | فیس پول سیم‌کش (هر دو نسخه یکسان) | فیس پول سیم‌کش |\n| دوشنبه | پک‌دک معکوس | پک‌دک معکوس | نشر خم دمبل |\n| دوشنبه | جلوبازو هالتر خمیده | جلوبازو سیم‌کش | جلوبازو هالتر خمیده |\n| دوشنبه | پول‌اور سیم‌کش دست صاف | پول‌اور سیم‌کش دست صاف (هر دو نسخه یکسان) | پول‌اور سیم‌کش دست صاف |\n| چهارشنبه | پرس پا دستگاه | پرس پا دستگاه | اسکات گلابی دمبل |\n| چهارشنبه | ددلیفت رومانیایی | بک اکستنشن دستگاه (۴۵ درجه) | ددلیفت رومانیایی |\n| چهارشنبه | اسکات بلغاری | پرس پا تک‌پا | اسکات بلغاری |\n| چهارشنبه | پشت‌پا خوابیده | پشت‌پا خوابیده (هر دو نسخه یکسان) | پشت‌پا خوابیده |\n| چهارشنبه | ساق پا ایستاده | ساق پا ایستاده (هر دو نسخه یکسان) | ساق پا ایستاده |\n| چهارشنبه | بالانش آویزان | بالانش با صندلی کاپیتان | بالانش آویزان |\n| چهارشنبه | شکم سیم‌کش زانوزده | شکم سیم‌کش زانوزده (هر دو نسخه یکسان) | شکم سیم‌کش زانوزده |\n\n## جلسه ۱ — Push — شنبه (۶۰ تا ۷۵ دقیقه)\n\n**چرا این روز:** سینه‌ی کامل و سرشانه‌ی گرد و پهن، خط اول فرم شناگریه. بالاسینه قوی باعث می‌شه لباس رو تن بهتر بشینه و شونه‌ها پهن‌تر دیده بشن.\n\n**کاردیو روز:** ۱۵ تا ۲۰ دقیقه تردمیل شیب‌دار (سرعت ۵–۶ / شیب ۵–۸٪ / ضربان ۱۱۰–۱۳۵)\n\n### ۱.۱ پرس سینه هالتر — `Bench Press (Barbell)`\n\n- **عضله:** سینه، سرشانه جلویی، پشت‌بازو | **دوز:** ۴ ست × ۵ تا ۸ | **استراحت:** ۲–۳ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - تیغه‌های شانه رو عقب و پایین قفل کن و قفسه سینه رو باد کن\n  - هالتر رو روی خط نوک سینه پایین بیار؛ آرنج‌ها حدود ۴۵ تا ۷۰ درجه نسبت به بدن\n  - پاها محکم رو زمین — اولین فشار از پاها میاد، بعد پرس\n- **خطاهای رایج:**\n  - لگد زدن هالتر از سینه (bounce)\n  - بالا اومدن باسن از نیمکت\n- **نسخه‌های جایگزین:**\n  - دستگاه: پرس سینه دستگاه (Chest Press (Machine)) — مسیر ثابت و بدون ریسک گیر کردن زیر وزنه — تمرکزت می‌مونه روی سینه. از هفته ۳–۴ پرس هالتر رو با میله خالی اضافه کن.\n> ★ گرم‌کردن این حرکت: ۱×۸ ۴۰٪ → ۱×۴ ۶۰٪ → ۱×۲ ۷۵٪ (درصد از وزنه ست اول)\n\n### ۱.۲ پرس بالاسینه دمبل — `Incline Bench Press (Dumbbell)`\n\n- **عضله:** بالاسینه، سرشانه جلویی | **دوز:** ۳ ست × ۸ تا ۱۲ | **استراحت:** ۲ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - شیب نیمکت ۳۰ درجه — بیشتر بشه سرشانه فعال‌تر می‌شه، کمتر بشه سینه پایین\n  - دمبل‌ها رو با مسیر کمی مورب به هم نزدیک کن و بالای سینه اسکوییز کن\n  - در پایین حرکت کشش رو حس کن، شونه‌ها رو نکش روون\n- **خطاهای رایج:**\n  - قوس شدید کمر\n  - برخورد دمبل‌ها به هم بالای سر (فقط نزدیک کن)\n- **نسخه‌های جایگزین:**\n  - دستگاه: پرس بالاسینه دستگاه (Incline Chest Press (Machine)) — همون الگوی حرکتی، بدون دغدغه کنترل دو دمبل جدا — عالی برای هفته‌های یادگیری.\n\n### ۱.۳ پرس سرشانه دمبل نشسته — `Shoulder Press (Dumbbell)`\n\n- **عضله:** سرشانه (دلتوئید قدامی و جانبی)، پشت‌بازو | **دوز:** ۳ ست × ۸ تا ۱۲ | **استراحت:** ۲ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - پشتت کامل به پشتی نیمکت بچسبه؛ قوس کمر طبیعی و کم\n  - دمبل‌ها تا امتداد گوش پایین بیار و بدون قفل کامل آرنج بالا برو\n  - مچ‌ها صاف و در امتداد ساعد باشن\n- **خطاهای رایج:**\n  - قوس زیاد کمر برای بلند کردن وزنه سنگین‌تر\n  - باز کردن بیش از حد دمبل‌ها به پهلو\n- **نسخه‌های جایگزین:**\n  - دستگاه: پرس سرشانه دستگاه (Seated Shoulder Press (Machine)) — پشتی دستگاه قوس کمر رو کنترل می‌کنه — ریسک کمتر، تمرکز بیشتر روی دلتوئید.\n\n### ۱.۴ کراس اور سیم‌کش سینه — `Cable Fly Crossovers`\n\n- **عضله:** سینه (به‌خصوص داخلی) | **دوز:** ۳ ست × ۱۰ تا ۱۵ | **استراحت:** ۷۵–۹۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - قوس دست‌ها در کل حرکت ثابت بمونه — مثل در آغوش گرفتن یه درخت\n  - در انتهای حرکت ۱ ثانیه سینه رو اسکوییز کن\n  - یک پا جلو بذار و تنه رو کمی مایل کن برای ثبات\n- **خطاهای رایج:**\n  - تبدیل‌شدن به پرس با خم کردن آرنج‌ها\n  - کشیدن وزنه با کمر و سوئینگ بدن\n- **نسخه‌های جایگزین:**\n  - وزنه آزاد: قفسه سینه دمبل (Chest Fly (Dumbbell)) — وقتی دستگاه شلوغه — کشش عمیق‌تر ولی کنترلش سخت‌تره؛ وزنه سبک انتخاب کن.\n\n### ۱.۵ پشت‌بازو سیم‌کش با طناب — `Triceps Rope Pushdown`\n\n- **عضله:** پشت‌بازو | **دوز:** ۳ ست × ۱۰ تا ۱۵ | **استراحت:** ۶۰–۹۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - آرنج‌ها چسبیده به بدن و ثابت — فقط ساعد حرکت می‌کنه\n  - پایین حرکت طناب رو کمی از هم باز کن و پشت‌بازو رو اسکوییز کن\n  - بالا رفتن رو آهسته و کنترل‌شده انجام بده\n- **خطاهای رایج:**\n  - خم شدن به جلو و فشار با وزن بدن\n  - دور شدن آرنج‌ها از بدن\n\n### ۱.۶ نشر جانب دمبل — `Lateral Raise (Dumbbell)`\n\n- **عضله:** سرشانه جانبی — کلید فرم V | **دوز:** ۷ ست × ۱۰ تا ۱۵ | **استراحت:** ۳۰–۴۵ ثانیه | **RPE:** پامپ | ★ **FST-7**\n- **نکات فرم:**\n  - شونه‌ها پایین و عقب — ترپس رو درگیر نکن\n  - آرنج کمی خم و همیشه بالاتر از مچ حرکت کنه\n  - فقط تا خط شانه بالا بیا؛ پایین‌اومدن کنترل‌شده (۲–۳ ثانیه)\n- **خطاهای رایج:**\n  - سوئینگ و پرتاب دمبل با کمر\n  - بالاتر از شانه بردن با ترپس\n- **نسخه‌های جایگزین:**\n  - دستگاه: نشر جانب سیم‌کش (Lateral Raise (Cable)) — تغییر وزنه بین ست‌ها با یک پیچ — برای ست‌های ۷گانه FST-7 ایده‌آله؛ خود رامبد هم برای FST-7 اغلب کابل/دستگاه استفاده می‌کنه.\n\n**پایان جلسه:** بعد از ست آخر: LISS دوچرخه ۱۵ تا ۲۰ دقیقه (ضربان ۱۱۵ تا ۱۳۵) — جایگزین تردمیل شیب‌دار\n**سرد کردن:** چارچوب در (سینه) — کراس‌بادی شانه — کودک\n\n## جلسه ۲ — Pull — دوشنبه (۶۰ تا ۷۵ دقیقه)\n\n**چرا این روز:** عرض پشت (لت‌ها) مهم‌ترین بخش فرم شناگریه. هر چه پهنت‌تر از کمرت، فرم V واضح‌تر. امروز روز طلایی توئه!\n\n**کاردیو روز:** استراحت فعال — پیاده‌روی ۸ تا ۱۰ هزار قدم (یا شنای سبک ۳۰ دقیقه)\n\n### ۲.۱ بارفیکس — `Pull Up`\n\n- **عضله:** لت‌ها (عرض پشت)، بالاپشت | **دوز:** ۴ ست × ۵ تا ۱۰ | **استراحت:** ۲–۳ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - دست‌ها کمی بازتر از عرض شانه، سینه به سمت میله\n  - قبل از کشیدن، شونه‌ها رو پایین و عقب بکش (depress)\n  - اگه کمتر از ۵ تا می‌زنی: Lat Pulldown با وزنه کم یا Pull Up (Assisted) — افتادن از تکرار نداریم!\n- **خطاهای رایج:**\n  - کیک زدن با پا\n  - نصفه دامنه (چانه فقط تا میله بدون اسکوییز لت)\n- **نسخه‌های جایگزین:**\n  - دستگاه: بارفیکس کمکی دستگاه (Pull Up (Assisted)) — فنر/وزنه متعادل‌کننده تا وقتی ۵ تکرار تمیز بدون کمک بزنی — هر هفته کمک رو کم کن.\n> ★ گرم‌کردن این حرکت: ۱ ست اسکاپولار پول + ۵ تکرار سبک با کش کمکی\n\n### ۲.۲ زیربغل هالتر خم — `Bent Over Row (Barbell)`\n\n- **عضله:** پشت میانی، لت‌ها، ذوزنقه | **دوز:** ۳ ست × ۶ تا ۱۰ | **استراحت:** ۲–۳ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - تنه حدود ۴۵ درجه، کمر صاف و هسته سفت\n  - هالتر رو به سمت ناف یا پایین سینه بکش — نه سینه بالا\n  - تیغه‌های شانه رو در انتهای حرکت به هم نزدیک کن\n- **خطاهای رایج:**\n  - دم کردن با کمر (بالا اومدن تنه هر ست)\n  - کشش با بازو به جای پشت\n- **نسخه‌های جایگزین:**\n  - دستگاه: زیربغل سیم‌کش نشسته (Seated Cable Row - V Grip (Cable)) — ستون فقرات اتکا داره و فشار می‌مونه روی پشت. اگه دستگاه زیربغل سینه‌اتکایی (مثل هامر استرنث که دوریان ییتس می‌زد) بود، همون بهترینه.\n\n### ۲.۳ زیربغل سیم‌کش دست‌باز — `Lat Pulldown (Cable)`\n\n- **عضله:** لت‌ها — عرض پشت | **دوز:** ۳ ست × ۱۰ تا ۱۲ | **استراحت:** ۲ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - دست کمی بازتر از شانه؛ دسته رو تا بالای سینه بکش\n  - در پایین حرکت لت‌ها رو اسکوییز کن و ۱ ثانیه نگه دار\n  - بازگشت کنترل‌شده تا کشش کامل در بالای پشت\n- **خطاهای رایج:**\n  - کشیدن دسته پشت گردن (خطرناک برای شانه)\n  - عقب رفتن زیاد بدن مثل قایق‌سواری\n\n### ۲.۴ فیس پول سیم‌کش — `Face Pull`\n\n- **عضله:** سرشانه خلفی، سلامت شانه | **دوز:** ۳ ست × ۱۲ تا ۱۵ | **استراحت:** ۷۵–۹۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - طناب در ارتفاع صورت؛ به سمت پیشونی بکش نه سینه\n  - در انتها دست‌ها رو بیرون بچرخون (external rotation)\n  - این حرکت صندوقچه‌ی سلامت شانه‌ست — سنگینی برات مهم نیست\n- **خطاهای رایج:**\n  - وزنه سنگین → تبدیل به زیربغل\n  - کشیدن با کمر به جای شانه خلفی\n\n### ۲.۵ پک‌دک معکوس — `Rear Delt Reverse Fly (Machine)`\n\n- **عضله:** ذوزنقه میانی (تراپز میانی)، سرشانه خلفی | **دوز:** ۳ ست × ۱۲ تا ۱۵ | **استراحت:** ۶۰–۹۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - سینه چسبیده به پد، تنه ثابت — حرکت فقط از شانه‌ها\n  - بازوها کمی خم و قفل؛ عقب بردن با جمع کردن تیغه‌های شانه، نه با دست\n  - انتهای حرکت ۱ ثانیه تراپز میانی رو اسکوییز کن\n  - شونه‌ها پایین نگه‌دار — اگر بالا اومد یعنی تراپز بالا دزدیده\n- **خطاهای رایج:**\n  - وزنه سنگین → سوئینگ و کمک گرفتن از کمر\n  - بالا انداختن شانه‌ها به سمت گوش\n  - باز کردن قفل آرنج وسط حرکت\n- **نسخه‌های جایگزین:**\n  - وزنه آزاد: نشر خم دمبل (Rear Delt Reverse Fly (Dumbbell)) — وقتی دستگاه شلوغه — تنه موازی زمین، دمبل سبک، همون جمع کردن تیغه‌ها در انتها.\n\n### ۲.۶ جلوبازو هالتر خمیده — `EZ Bar Biceps Curl`\n\n- **عضله:** جلوبازو | **دوز:** ۳ ست × ۸ تا ۱۲ | **استراحت:** ۹۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - آرنج‌ها ثابت کنار بدن — فقط ساعد حرکت می‌کنه\n  - پایین‌اومدن کنترل‌شده ۲ تا ۳ ثانیه‌ای\n  - دستگيره رو کمی بچرخون (supinate) بالای حرکت برای اسکوییز بیشتر\n- **خطاهای رایج:**\n  - سوئینگ کمر و پرتاب هالتر\n  - جلو آوردن آرنج‌ها هنگام بالا بردن\n- **نسخه‌های جایگزین:**\n  - دستگاه: جلوبازو سیم‌کش (Bicep Curl (Cable)) — کشش بیسپس در کل دامنه + سوئینگ کمر عملاً غیرممکن — فرم تمیز از روز اول.\n\n### ۲.۷ پول‌اور سیم‌کش دست صاف — `Straight Arm Lat Pulldown (Cable)`\n\n- **عضله:** لت‌ها — پامپ و کشش فاسیا | **دوز:** ۷ ست × ۱۰ تا ۱۵ | **استراحت:** ۳۰–۴۵ ثانیه | **RPE:** پامپ | ★ **FST-7**\n- **نکات فرم:**\n  - آرنج ثابت و کمی خم — زاویه دست در کل حرکت ثابت\n  - با لت‌ها دسته رو تا ران بکش و انتهای حرکت اسکوییز کن\n  - فاصله مناسب از دستگاه تا کشش کامل بالای پشت حفظ بشه\n- **خطاهای رایج:**\n  - خم کردن آرنج → تبدیل به پوش‌داون\n  - استفاده از شانه و ترپس به جای لت\n\n**پایان جلسه:** بعد از ست آخر: LISS دوچرخه ۱۵ تا ۲۰ دقیقه (ضربان ۱۱۵ تا ۱۳۵) — جایگزین تردمیل شیب‌دار\n**سرد کردن:** کشش لت روی دیوار — آویزان‌شدن از بارفیکس — گربه–گاو\n\n## جلسه ۳ — پا + شکم — چهارشنبه (۷۰ تا ۸۵ دقیقه)\n\n**چرا این روز:** عضلات پا بزرگ‌ترین مصرف‌کننده کالری بدنن و رشدشون متابولیسمت رو بالا می‌بره. پا قوی = کاهش وزن سریع‌تر و بدن متقارن. بدون پا، فرم شناگری ناقصه!\n\n**کاردیو روز:** ۱۵ تا ۲۰ دقیقه پیاده‌روی تند یا دوچرخه ثابت + کشش کامل پا\n\n### ۳.۱ پرس پا دستگاه — `Leg Press (Machine)`\n\n- **عضله:** چهارسر، باسن | **دوز:** ۴ ست × ۸ تا ۱۲ | **استراحت:** ۲–۳ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - پاها عرض شانه وسط صفحه — کف پا کامل روی صفحه\n  - تا ۹۰ درجه یا کمی کمتر پایین بیا؛ باسن از صندلی جدا نشه\n  - بالا ارنج رو کامل قفل نکن — فشار همیشه روی عضله بمونه\n- **خطاهای رایج:**\n  - نصفه دامنه با وزنه خیلی سنگین\n  - بالا اومدن باسن و گردن‌انداختن کمر\n- **نسخه‌های جایگزین:**\n  - وزنه آزاد: اسکات گلابی دمبل (Goblet Squat) — برای تنوع یا تمرین در خانه/سفر — دمبل رو کنار سینه بگیر و عمیق پایین برو.\n> ★ گرم‌کردن این حرکت: ۱×۱۰ ۴۰٪ → ۱×۵ ۶۰٪ → ۱×۳ ۷۵٪ (درصد از وزنه ست اول)\n\n### ۳.۲ ددلیفت رومانیایی — `Romanian Deadlift (Barbell)`\n\n- **عضله:** همسترینگ، باسن، فیله کمر | **دوز:** ۳ ست × ۸ تا ۱۰ | **استراحت:** ۲–۳ دقیقه | **RPE:** ۸\n- **نکات فرم:**\n  - لگن رو به عقب هل بده (hip hinge) — اسکات نیست!\n  - هالتر تمام مدت چسبیده به پا پایین میاد\n  - در پایین کشش همسترینگ رو حس کن، کمر صاف و سینه باز\n- **خطاهای رایج:**\n  - خم شدن کمر و گردنی شدن هالتر جلو\n  - زانوی زیاد خم → تبدیل به اسکات\n- **نسخه‌های جایگزین:**\n  - دستگاه: بک اکستنشن دستگاه (۴۵ درجه) (Back Extension (Machine)) — همون زنجیره پشتی (همسترینگ/باسن/فیله) با محافظت کامل کمر — RDL رو بعد هفته ۲–۳ با دمبل سبک برگردون.\n\n### ۳.۳ اسکات بلغاری — `Bulgarian Split Squat (Dumbbell)`\n\n- **عضله:** چهارسر، باسن، تعادل | **دوز:** ۳ ست × ۸ تا ۱۲ هر پا | **استراحت:** ۹۰ ثانیه | **RPE:** ۸\n- **نکات فرم:**\n  - پنجه پای عقب روی نیمکت، پای جلو حدود ۶۰ سانت جلوتر\n  - تنه رو کمی مایل به جلو بیار تا باسن بیشتر درگیر بشه\n  - زانوی جلو در امتداد پنجه پا حرکت کنه، نه داخل‌تر\n- **خطاهای رایج:**\n  - گام خیلی کوتاه → فشار روی زانو\n  - اتکا و پرش با پای عقبی\n- **نسخه‌های جایگزین:**\n  - دستگاه: پرس پا تک‌پا (Single Leg Press (Machine)) — همون کار یک‌پا بدون دغدغه تعادل — هر پا جداگانه ثبت کن.\n\n### ۳.۴ پشت‌پا خوابیده — `Lying Leg Curl (Machine)`\n\n- **عضله:** همسترینگ | **دوز:** ۳ ست × ۱۰ تا ۱۵ | **استراحت:** ۷۵ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - لگن تمام مدت چسبیده به دستگاه — باسن بالا نیاد\n  - پنجه پا رو به سمت ساق جمع کن تا ساق کمتر وارد بشه\n  - برگشت کنترل‌شده ۲ تا ۳ ثانیه\n- **خطاهای رایج:**\n  - بالا کشیدن لگن با کمک کمر\n  - دامنه ناقص\n\n### ۳.۵ ساق پا ایستاده — `Standing Calf Raise`\n\n- **عضله:** ساق | **دوز:** ۴ ست × ۱۰ تا ۱۵ | **استراحت:** ۶۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - دامنه کامل: پایین کشش ۲ ثانیه، بالا اسکوییز ۱ ثانیه\n  - پنجه‌ها رو روی یک صفحه/دمبل بذار تا دامنه بیشتر بشه\n  - زانو صاف و ثابت در کل حرکت\n- **خطاهای رایج:**\n  - ریتم سریع باکونس\n  - نصفه دامنه بدون کشش پایین\n\n### ۳.۶ بالانش آویزان — `Hanging Leg Raise`\n\n- **عضله:** شکم پایینی، هسته | **دوز:** ۳ ست × ۸ تا ۱۵ | **استراحت:** ۹۰ ثانیه | **RPE:** ۹\n- **نکات فرم:**\n  - کلید حرکت چرخش لگنه (posterior pelvic tilt) — نه فقط بالا بردن پا\n  - بدون تاب خوردن؛ پایین‌اومدن کنترل‌شده\n  - اگه سخته: زانوها خم (knee raise) — افتادن از فرم نداریم\n- **خطاهای رایج:**\n  - تاب خوردن از شانه‌ها\n  - پا رفت بالا ولی لگن ثابت موند → شکم کار نکرد\n- **نسخه‌های جایگزین:**\n  - دستگاه: بالانش با صندلی کاپیتان (Leg Raise Parallel Bars) — پشتی از کمر حمایت می‌کنه و تاب خوردن حذف می‌شه — تمرکز روی چرخش لگن.\n\n### ۳.۷ شکم سیم‌کش زانوزده — `Cable Crunch`\n\n- **عضله:** شکم (رکتوس آبدومینیس) | **دوز:** ۷ ست × ۱۲ تا ۱۵ | **استراحت:** ۳۰–۴۵ ثانیه | **RPE:** پامپ | ★ **FST-7**\n- **نکات فرم:**\n  - دسته رو کنار گردن بگیر (نه پشت سر) و زانوها روی زمین\n  - ستون فقرات رو جمع کن — حس کن شکم داره فشرده می‌شه\n  - چند قدم از دستگاه فاصله بگیر تا کشش کامل حفظ بشه\n- **خطاهای رایج:**\n  - کشیدن با بازو\n  - خم شدن از لگن به جای جمع کردن ستون فقرات\n\n**پایان جلسه:** بعد از ست آخر: LISS دوچرخه ۱۵ تا ۲۰ دقیقه (ضربان ۱۱۵ تا ۱۳۵) — جایگزین تردمیل شیب‌دار\n**سرد کردن:** همسترینگ با بند — چهارسر ایستاده — فلکسور ران — ساق روی دیوار\n\n## 🚴 برنامهٔ دوچرخه ثابت (خانه)\n\n### گرم‌کردن قبل از وزنه\n- **کی:** شنبه، دوشنبه، چهارشنبه — قبل از ست اول\n- **دوز:** ۵ دقیقه خیلی آسان (مقاومت کم)\n- **چطور:** ریتم پدال راحت — جوری که راحت حرف بزنی. بعدش برای حرکت اول جلسه، یک ست سبک اضافه بزن.\n- **چرا:** دما و جریان خون عضله بالا می‌رود؛ گرم‌کردن هوازی قبل تمرین مقاومتی کوفتگی بعد تمرین را کم می‌کند (Olsen 2012).\n\n### کاردیوی LISS بعد از وزنه ⭐\n- **کی:** همان روزهای وزنه — بعد از ست آخر\n- **دوز:** ۱۵–۲۰ دقیقه • ضربان ۱۱۵–۱۳۵\n- **چطور:** جایگزین تردمیل شیب‌دار در برنامه: مقاومت متوسط، ضربان را با ساعت هوشمند یا شمارنده دوچرخه چک کن.\n- **چرا:** چربی‌سوزی با ضربان کنترل‌شده، بدون فشار زانو و بدون گرمای بیرون.\n\n### ریکاوری فعال روز استراحت\n- **کی:** یکشنبه، سه‌شنبه، پنجشنبه، جمعه — اختیاری\n- **دوز:** ۲۰–۳۰ دقیقه خیلی آسان • ضربان زیر ~۱۱۵\n- **چطور:** جایگزین یا مکمل پیاده‌روی ۸–۱۰ هزار قدم. ریلکس پدال بزن — نه جوری که عرق شدید کنی.\n- **چرا:** جریان خون = ریکاوری سریع‌تر و کوفتگی کمتر، بدون فشار اضافه به بدن.\n\n**تنظیم زین:** تنظیم زین: ایستاده کنار دوچرخه، زین هم‌سطح استخوان لگن؛ در پایین‌ترین نقطهٔ پدال، زانو ۲۵–۳۰ درجه خم بماند.\n\n> ⚠️ HIIT روی دوچرخه حداکثر ۱ بار در هفته و فقط وقتی خواب و تغذیه‌ت خوب بوده. روز استراحت = ریکاوری، نه تمرین دوم — اگر فردایش خسته‌ای، دوچرخه را نصف کن (قانون ریکاوری منتزر).\n\n## 🧘 روتین کششی روزانه (~۱۰ دقیقه — بعد از تمرین یا شب)\n\n| # | حرکت | ناحیه | دوز | چطور |\n|---|---|---|---|---|\n| ۱ | گردن (خم جانبی) — Side Neck Stretch | گردن و شانه | ۲ × ۲۰ ثانیه هر طرف | نشسته یا ایستاده، تنه صاف؛ دست را روی سر بگذار و آرام به سمت کنار بکش — شانه مقابل پایین و شل. هرگز به عقب نکش. |\n| ۲ | کراس‌بادی شانه — Cross-Body Shoulder Stretch | گردن و شانه | ۳۰ ثانیه هر طرف | دست را افقی روی سینه بیاور؛ با دست دیگر آرنج را به سمت سینه قفل کن. شانه پایین، تنه ثابت. |\n| ۳ | سینه در چارچوب در — Doorway Pec Stretch | سینه و پشت | ۲۰–۳۰ ثانیه هر طرف | ساعد روی چارچوب در، آرنج هم‌سطح شانه؛ یک قدم جلو و تنه را بچرخان تا جلوی شانه کشیده شود. |\n| ۴ | کشش لت روی دیوار — Wall Lat Stretch | سینه و پشت | ۳۰ ثانیه هر طرف | دست‌ها بالای دیوار/چارچوب، لگن را عقب بده و سینه را پایین بین بازوها — کشش از زیربغل تا پهلو. |\n| ۵ | گربه–گاو — Cat-Cow | کمر و ستون | ۸ تکرار آهسته | چهار دست‌وپا؛ با دم کمر را گوهی خم کن، با بازدم قوس بده و نگاه بالا. مهره‌به‌مهره، بدون عجله. |\n| ۶ | چرخش پشتی (کتاب باز) — Open Book Thoracic Rotation | کمر و ستون | ۳۰ ثانیه هر طرف | به پشت خوابیده، زانوها خم و روی هم؛ هر دو زانو را آرام به یک طرف رها کن و دستِ مقابل را باز کن رو زمین و نگاه را دنبالش ببر. |\n| ۷ | کبرا (مک‌کنزی) ⭐ — Cobra / McKenzie Extension | کمر و ستون | ۲ × ۲۰–۳۰ ثانیه | رو شکم، کف دست‌ها کنار سینه؛ تنه را بالا بیار — اول با عضله کمر، بعد اگر راحت بود با کمک دست. لگن چسبیده به زمین. |\n| ۸ | کودک — Child's Pose | کمر و ستون | ۴۵ ثانیه | زانوها کمی باز، باسن روی پاشنه، دست‌ها جلو و پیشونی روی زمین. با هر بازدم ۱–۲ سانت عمیق‌تر. |\n| ۹ | لانژ پایین (فلکسور ران) ⭐ — Low Lunge Hip Flexor Stretch | لگن و باسن | ۲ × ۳۰ ثانیه هر پا | یک زانو زمین، پای جلو ۹۰ درجه؛ تنه صاف، باسن را جمع کن و لگن را آرام به جلو هل بده تا جلوی ران کشیده شود. |\n| ۱۰ | شکل ۴ (باسن) ⭐ — Figure-4 Glute Stretch | لگن و باسن | ۲ × ۳۰ ثانیه هر طرف | پشت خوابیده، مچ پای جلو روی ران پای مقابل؛ پای مقابل را به سمت سینه بکش. کشش را در باسن حس کن. |\n| ۱۱ | همسترینگ (با بند) ⭐ — Supine Hamstring Stretch | پا | ۲ × ۳۰ ثانیه هر پا | پشت دراز بکش، پا را با حوله یا بند بالا بکش تا کشش ملایم پشت ران؛ زانو تقریباً صاف ولی قفل نه. |\n| ۱۲ | چهارسر ایستاده — Standing Quad Stretch | پا | ۳۰ ثانیه هر پا | ایستاده (یا با دست روی دیوار)، مچ پا را بگیر و پاشنه را به باسن نزدیک کن — زانوها کنار هم، لگن جمع. |\n| ۱۳ | ساق روی دیوار — Wall Calf Stretch | پا | ۳۰ ثانیه هر پا | دست‌ها روی دیوار، پای عقب صاف با پاشنه چسبیده به زمین؛ به جلو خم شو تا ساق کشیده شود. زانوی پای عقب صاف. |\n| ۱۴ | آویزان‌شدن از بارفیکس — Dead Hang | سینه و پشت | ۲۰–۳۰ ثانیه | از میله آویزان شو، شانه‌ها فعال و کمی پایین، نفس آرام. بگذار ستون فقرات باز شود. |\n\n⭐ = کلیدی برای کمر. کشش اختیاری: آویزان‌شدن از بارفیکس (دکامپرشن کمر).\n\n- **روزهای وزنه:** بعد از وزنه و کاردیو — نه قبل از تمرین! کششِ طولانیِ قبل وزنه افت قدرت می‌دهد (Behm 2016).\n- **روزهای استراحت:** هر ساعتی — ترجیحاً شب، بعد از پیاده‌روی یا ۵ دقیقه دوچرخه سبک تا بدن گرم باشد.\n- **قانون طلایی:** هر روز ~۱۰ دقیقه کل بدن. ثباتِ روزانه از ۱۵ دقیقهِ گاه‌به‌گاه قوی‌تر است — ACSM: هر عضله مجموع ~۶۰ ثانیه در روز.\n\n۱. شدت کشش ۴–۵ از ۱۰ — احساس کشش بده، نه درد؛ هرگز فشار تند نکن\n۲. نفس آرام و عمیق در کل نگه‌داشتن — بازدم طولانی تنش عصبی را کم می‌کند\n۳. بدن سرد = کشش ممنوع — حداقل ۵ دقیقه حرکت سبک قبلش (دوچرخه‌ت عالیه!)\n۴. انتظار واقعی: تفاوت محسوس ۴–۸ هفته — بعدش دامنهٔ اسکوات و ددلیفت هم تمیزتر می‌شود\n\n## 📈 قواعد پیشرفت\n\n- **پیشروی دوگانه:** وقتی در همه ست‌ها به سقف تکرار رسیدی با فرم تمیز → وزنه رو +۲.۵ کیلو (بالاتنه) یا +۵ کیلو (پا) ببر و دوباره از کف تکرار شروع کن.\n- **قانون RPE ۷–۹:** همیشه ۱ تا ۳ تکرار «در مخزن» نگه دار. تا ناتوانی مطلق نرو — ریکاوری گرون‌تر از تمرینه.\n- **دیلود هر ۶–۸ هفته:** یک هفته با نصف وزنه‌ها تمرین کن. بدنت بازسازی می‌شه و بعدش قوی‌تر برمی‌گردی.\n- **قانون جلسه ۷۵ دقیقه‌ای:** جلسه‌ها رو زیر ۷۵ دقیقه نگه دار — کورتیزول بعد از این مدت اوج می‌گیره و مضر می‌شه.\n\n## ⭐ FST-7 — چیست FST-7؟ (امضای هانی رامبد)\n\nسیستم ستاره‌ساز هانی رامبد — مربی ۱۹ بار مستر المپیا (فیث هیت، کریس بامستید، جی کاتلر). در پایان هر جلسه، حرکت ایزوله‌ی انتخابی را ۷ ست با استراحت فقط ۳۰–۴۵ ثانیه اجرا می‌کنی تا خون به بیشینه وارد عضله بشه، فاسیا (پوشش عضله) کشیده و باز بشه و فضای رشد عضله بیشتر بشه.\n\n- ۷ ست × ۱۰–۱۵ تکرار با استراحت فقط ۳۰–۴۵ ثانیه\n- وزنه متوسط — پامپ مهم‌تر از سنگینی است\n- بین ست‌ها عضله رو کشش بده و آب بنوش\n- سنگینی‌ها اول جلسه (حرکات چندمفصلی)، پامپ آخر جلسه\n\n## 🥗 تغذیه\n\n- **کسری کالری:** حدود ۵۰۰ کالری زیر نیاز روزانه → هدف: کاهش ۰.۵ تا ۰.۷ کیلو در هفته. سریع‌تر از این یعنی عضله هم داری می‌سوزونی.\n- **پروتئین:** حدود ۱۶۰ تا ۱۸۰ گرم در روز (۲ گرم × وزن هدف). هر وعده ۳۰–۴۰ گرم: مرغ، تخم‌مرغ، ماهی، لبنیات کم‌چرب.\n- **کراتین:** ۳ تا ۵ گرم هر روز — در کسری کالری کمک می‌کنه قدرت و عضله حفظ بشه. نیازی به لودینگ نیست.\n- **خواب:** ۷ تا ۹ ساعت شبانه — بهترین داروی طبیعی کورتیزول. قبل از نیمه‌شب بخواب.\n- **آب:** روزانه ۳ تا ۳.۵ لیتر — هم برای چربی‌سوزی، هم برای عملکرد و ریکاوری بهتر.\n- **کاردیو:** LISS (پیاده‌روی/شنا) پایه‌ست؛ HIIT حداکثر ۱ جلسه کوتاه در هفته. روزانه ۸–۱۰ هزار قدم.\n\n---\n\n**قاعدهٔ طلایی: ثبت‌نکردن = تمرین‌نکردن.** هر ست را لاگ کن؛ هفته بعد را همان لاگ تصمیم می‌گیرد.",
};

